reference_solution.python:
class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        prefix_sum = {0: 1}
        curr_sum = 0
        count = 0
        for n in nums:
            curr_sum += n
            count += prefix_sum.get(curr_sum - k, 0)
            prefix_sum[curr_sum] = prefix_sum.get(curr_sum, 0) + 1
        return count

reference_solution.javascript:
function subarraySum(nums, k) {
    const prefixSum = new Map();
    prefixSum.set(0, 1);
    let currSum = 0, count = 0;
    for (const n of nums) {
        currSum += n;
        count += prefixSum.get(currSum - k) || 0;
        prefixSum.set(currSum, (prefixSum.get(currSum) || 0) + 1);
    }
    return count;
}
